import { useSyncExternalStore } from 'react';
import { latestPr, type Changelog, type ChangelogEntry } from '../../shared/changelog';
import rawLog from '../../content/changelog/changelog.json';
import rawPl from '../../content/changelog/changelog.pl.json';
import type { Lang } from '../i18n';

/** The changelog the app ships (generated by `npm run changelog`, see src/shared/changelog.ts). */
export const changelog = rawLog as Changelog;
/** Polish texts written by hand for recent changes, by pull request number. */
export const changelogPl = rawPl as Record<string, string>;

/** The text of a change in a language: the Polish one when written, else the English title. */
export function entryText(e: ChangelogEntry, lang: Lang): { text: string; lang: Lang } {
  const pl = lang === 'pl' ? changelogPl[String(e.pr)] : undefined;
  return pl ? { text: pl, lang: 'pl' } : { text: e.title, lang: 'en' };
}

/**
 * The recent days (from the oldest day with a hand-written Polish text on, shown open; a change
 * newer than the Polish texts shows its English title) and the older days (folded on the page).
 */
export function splitDays<D extends { date: string; entries: ChangelogEntry[] }>(
  days: readonly D[],
  pl: Readonly<Record<string, string>> = changelogPl,
): { recent: D[]; older: D[] } {
  let from = '';
  for (const d of days) if (d.entries.some((e) => String(e.pr) in pl)) from = d.date;
  if (from === '') return { recent: [], older: [...days] };
  return { recent: days.filter((d) => d.date >= from), older: days.filter((d) => d.date < from) };
}

/**
 * The newest change the rider has seen on "What's new" (its pull request number). The dot next to
 * "How it works" and in the footer shows while the changelog has a newer one; opening the page
 * clears it. Never a popup (the owner's rule: messages do not shout).
 */
export const WHATS_NEW_KEY = 'hypercycling.whatsNew.seen';

const listeners = new Set<() => void>();

function readSeen(): number {
  try {
    const v = Number(localStorage.getItem(WHATS_NEW_KEY));
    return Number.isFinite(v) ? v : 0;
  } catch {
    // Storage blocked: no dot rather than a dot that never goes away.
    return Number.POSITIVE_INFINITY;
  }
}

/** True while the changelog has a change newer than the last one seen. */
export function hasUnseen(log: Changelog = changelog): boolean {
  return latestPr(log) > readSeen();
}

/** Marks every change of the changelog as seen (on opening "What's new"). */
export function markSeen(log: Changelog = changelog): void {
  try {
    localStorage.setItem(WHATS_NEW_KEY, String(latestPr(log)));
  } catch {
    return;
  }
  listeners.forEach((l) => l());
}

function subscribe(listener: () => void): () => void {
  listeners.add(listener);
  return () => listeners.delete(listener);
}

/** Whether to show the new-items dot; updates when "What's new" is opened. */
export function useWhatsNewDot(): boolean {
  return useSyncExternalStore(
    subscribe,
    () => hasUnseen(),
    () => false,
  );
}
